use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).ok();
    let name = match input.trim() {
        "" => "World",
        n => n,
    };
    println!("Hello, {}!", name);
    let squares: Vec<u32> = (1..=5).map(|n| n * n).collect();
    println!("Squares: {:?}", squares);
}

